import functools

def memoize(func):
    cache = {}
    @functools.wraps(func)
    def wrapper(n):
        if n not in cache:
            cache[n] = func(n)
            print(f'계산: {n}')
        return cache[n]
    return wrapper

@memoize
def triple(n):
    return n * 3

print(triple(4))
triple(4)
print(triple(7))
```
